fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Check that all vectors have the same length
    let len = dst.len();
    assert_eq!(src.len(), len, "src must have same length as dst");
    assert_eq!(mask.len(), len, "mask must have same length as dst");
    
    // Use iterators to build the result
    dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect()
}